'use strict';
let verificationReport=null,verificationArchive=null;
function verificationShell(){
 const area=$('liveVerification');if($('verificationEmpty'))return;
 const empty=document.createElement('div');empty.id='verificationEmpty';empty.className='verification-empty';empty.setAttribute('role','status');$('verificationStatus').after(empty);
 const pending=document.createElement('details');pending.className='pending-details';pending.id='pendingVerification';const summary=document.createElement('summary');summary.textContent='Pending periods & methodology';pending.append(summary);const body=document.createElement('div');body.id='pendingPeriodBody';pending.append(body);
 const table=area.querySelector('.resulttablewrap');table.after(pending);
 for(const p of [...area.querySelectorAll(':scope > p.subtle')])pending.append(p);
 const note=document.createElement('p');note.className='critical-meaning';note.textContent='CFSv2 sampled-mean temperature is compared with a CPC daily-extrema midpoint proxy. This is a diagnostic mismatch, not exact local forecast skill.';$('verificationStatus').before(note);
 const daily=document.createElement('p');daily.className='subtle';daily.textContent='Daily GFS accuracy is not yet scored: immutable issue-time daily forecasts and matched UTC-window observations are required first. Historical pilot results do not verify the next-seven-day briefing.';pending.append(daily);
}
function renderVerification(){if(!verificationReport)return;verificationShell();const r=verificationReport,n=r.counts,group=$('verificationGrouping').value,unit=fahrenheit?'°F':'°C',scale=fahrenheit?1.8:1;
 $('verificationStatus').textContent='CFSv2 archive · '+n.issuances+' issuance'+(n.issuances===1?'':'s')+' · checked '+r.generatedAt.slice(0,16).replace('T',' ')+' UTC';
 const empty=$('verificationEmpty');empty.replaceChildren();empty.hidden=!!n.verified;
 if(!n.verified){const title=document.createElement('strong');title.textContent='No completed verification periods yet';const p=document.createElement('p');p.textContent=n.pending+' forecast-location periods pending'+(n.missingObservations?' · '+n.missingObservations+' mature periods lack observations':'')+'. No accuracy score is available.';empty.append(title,p);}
 const area=$('liveVerification');area.querySelector('.resulthead').hidden=!n.verified;area.querySelector('.resulttablewrap').hidden=!n.verified;
 const tbody=$('verificationRows');tbody.replaceChildren();for(const row of r.temperature[group]||[]){if(!row.n)continue;const tr=document.createElement('tr');for(const [i,v]of [group==='byLead'?(row.leadWeek===9?'Days 57–60':`Week ${row.leadWeek}`):row.name,row.n,...['bias','mae','rmse'].map(k=>Number.isFinite(row[k])?(row[k]*scale).toFixed(2)+' '+unit:'—')].entries()){const td=document.createElement(i?'td':'th');if(!i)td.scope='row';td.textContent=v;tr.append(td)}tbody.append(tr)}
 $('verificationNotes').textContent=(r.warnings||[]).join(' ');area.querySelectorAll('th').forEach((el,i)=>{if(i>=2&&i<5)el.textContent=['Bias','MAE','RMSE'][i-2]+' '+unit});
 const body=$('pendingPeriodBody');body.replaceChildren();if(verificationArchive){const periods=verificationArchive.locations?.[0]?.periods||verificationArchive.periods||[];if(periods.length){const table=document.createElement('table');table.className='resulttable';table.innerHTML='<thead><tr><th>Period</th><th>Valid end (exclusive)</th><th>Earliest eligibility</th></tr></thead>';const tb=document.createElement('tbody');for(const period of periods){const end=period.intervalEndExclusive||period.validEndExclusive;if(!end)continue;const eligible=new Date(Date.parse(end)+(r.minimumLatencyDays||0)*86400000);const tr=document.createElement('tr');for(const v of [period.leadWeek?'Week '+period.leadWeek:'Valid period',end.slice(0,10),eligible.toISOString().slice(0,10)+' UTC']){const td=document.createElement('td');td.textContent=v;tr.append(td)}tb.append(tr)}table.append(tb);body.append(table)}}
 if(!body.children.length){const p=document.createElement('p');p.textContent='Eligibility starts only after each complete valid interval plus the '+r.minimumLatencyDays+'-day application latency buffer. This is not a guarantee of NOAA data availability. Open the immutable archive for exact intervals.';body.append(p)}
}
$('verificationGrouping').onchange=renderVerification;
fetch('data/verification.json').then(r=>{if(!r.ok)throw Error('Unavailable');return r.json()}).then(r=>{verificationReport=r;renderVerification();const path=r.archiveProvenance?.at(-1)?.path;if(path&&/^[a-zA-Z0-9_.-]+\.json$/.test(path))fetch('data/archive/'+path).then(r=>r.ok?r.json():null).then(a=>{verificationArchive=a;renderVerification()}).catch(()=>{})}).catch(()=>{$('verificationStatus').textContent='Observation comparison unavailable. No accuracy score is shown.'});
